if (internal_key.size() < 8) return false;
const char* raw = internal_key.data();
uint64_t packed = *reinterpret_cast<const uint64_t*>(raw + internal_key.size() - 8);
*type = packed >> 63;
*sequence = packed & 0x7fffffffffffffff;
user_key->clear();
if (!user_key->assign(internal_key.data(), internal_key.size() - 8)) return false;
return true;
// END_CODE

